const direction=dest.clone().sub(origin),distance=direction.length();direction.normalize();
const raycaster=new THREE.Raycaster(origin,direction,0,distance);
const nearbyDecor=decor.filter(o=>Math.abs(o.position.x-me.x)<Math.abs(origin.x-me.x)+o.scale.x/2+5&&Math.abs(o.position.z-me.z)<Math.abs(origin.z-me.z)+o.scale.z/2+5);
