const dirty=new Set();const insideHouse=obstacles.some(h=>h.kind==='houseRoof'&&Math.abs(me.x-h.x)<h.w/2&&Math.abs(me.z-h.z)<h.d/2);for(const o of decor){const between=occluded.has(o)||(insideHouse&&o.userData.occluder&&o.position.y>7);
if(between&&!o.userData.faded){const clone=o.userData.baseMaterial.clone();clone.transparent=true;clone.opacity=.15;clone.depthWrite=false;o.material=clone;o.userData.faded=true;o.visible=true;dirty.add(o.userData.batch)}
else if(!between&&o.userData.faded){o.material.dispose();o.material=o.userData.baseMaterial;o.userData.faded=false;o.visible=false;dirty.add(o.userData.batch)}
}
